{"output": "def transform(grid):
    """Move the non-background object next to the 2-line and draw an 8-line beyond it."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # The guide is a complete row or column of color 2.
    guide = None
    for r, row in enumerate(g):
        if all(v == 2 for v in row):
            guide = ("h", r)
            break
    if guide is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                guide = ("v", c)
                break
    if guide is None:
        return g

    obj = [(r, c, g[r][c]) for r in range(h) for c in range(w)
           if g[r][c] != bg and g[r][c] != 2]
    if not obj:
        return g

    axis, line = guide
    if axis == "h":
        # Translate the object on the side of the horizontal guide until its
        # nearest edge touches the guide, then place the 8 stripe one cell
        # beyond the object's far edge.
        rs = [r for r, c, v in obj]
        if max(rs) < line:
            delta = line - 1 - max(rs)
            new_line = min(rs) + delta - 1
        elif min(rs) > line:
            delta = line + 1 - min(rs)
            new_line = max(rs) + delta + 1
        else:
            delta, new_line = 0, None
        if new_line is None:
            return g
        for r, c, v in obj:
            g[r][c] = bg
        for r, c, v in obj:
            nr = r + delta
            if 0 <= nr < h:
                g[nr][c] = v
        if 0 <= new_line < h and new_line != line:
            g[new_line] = [8] * w
    else:
        cs = [c for r, c, v in obj]
        if max(cs) < line:
            delta = line - 1 - max(cs)
            new_line = min(cs) + delta - 1
        elif min(cs) > line:
            delta = line + 1 - min(cs)
            new_line = max(cs) + delta + 1
        else:
            delta, new_line = 0, None
        if new_line is None:
            return g
        for r, c, v in obj:
            g[r][c] = bg
        for r, c, v in obj:
            nc = c + delta
            if 0 <= nc < w:
                g[r][nc] = v
        if 0 <= new_line < w and new_line != line:
            for r in range(h):
                g[r][new_line] = 8
    return g

